
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_hcth_p76_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_hcth_p76", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.513264623969734e+00, -4.415834461163277e+00, -4.279439009150289e+00, -4.090780138155164e+00, -3.834353683478112e+00, -3.494608586719682e+00, -3.061224629229912e+00, -2.539789215199567e+00, -1.970376656609526e+00, -1.440375352843343e+00, -9.715325460242069e-01, -6.340491346315085e-01, -5.374497864315797e-01, -4.091415847802987e-01, -2.744164978830080e-01, -1.630164062195963e-01, -1.464061278789505e-01, -3.867794704248054e-02, -2.267523500579616e-03, 2.306104715020183e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


